def proverb(*pieces, qualifier=None):
    """Return the lines of the proverb for the given pieces.

    Each consecutive pair of pieces produces a "For want of a X the Y was lost."
    line, and the final line always refers back to the first piece.
    """
    if not pieces:
        return []

    lines = [
        f"For want of a {current} the {next_} was lost."
        for current, next_ in zip(pieces, pieces[1:])
    ]

    if qualifier:
        lines.append(f"And all for the want of a {qualifier} {pieces[0]}.")
    else:
        lines.append(f"And all for the want of a {pieces[0]}.")

    return lines
